import csv
import json
import os
import sys
from collections import defaultdict

from pyscipopt import Model, quicksum

DATA_DIR = "/app/data"
SUB_DIR = "/app/submissions"
SOLUTION_PATH = os.path.join(SUB_DIR, "solution.csv")
MODEL_PATH = os.path.join(SUB_DIR, "model.md")
LOG_PATH = os.path.join(SUB_DIR, "solve_log.md")


def read_csv(path):
    with open(path, newline="") as f:
        return list(csv.DictReader(f))


def read_config():
    with open(os.path.join(DATA_DIR, "config.json")) as f:
        return json.load(f)


def write_model_md():
    os.makedirs(SUB_DIR, exist_ok=True)
    with open(MODEL_PATH, "w") as f:
        f.write("# Robotic Mobile Fulfillment Orchestration - Mathematical Model\n\n")
        f.write("## Sets\n- Orders o in O (42), lines l in L_o with SKU s_ol and qty q_ol.\n")
        f.write("- Pods p in P (30) with home zone, temperature capability, weight class, return buffer.\n")
        f.write("- Stations st in S (3) with visit/slot cap, units/visit, chargers, cold/hazmat flags.\n")
        f.write("- Robots r in R (6) with shift, battery params, charge rate.\n")
        f.write("- Slots t = 0..71. Aisle groups a with slot capacities.\n")
        f.write("- Promise groups g with target spread.\n\n")
        f.write("## Variables\n- z[opstt] in {0,1}: visit of pod p to station st at slot t serving order o.\n")
        f.write("- x[olpstt] in Z+ : qty of line l of order o picked from pod p at (st,t).\n")
        f.write("- a[opsttr] in {0,1}: robot r executes visit (o,p,st,t).\n")
        f.write("- ch[rstt] in {0,1}, d[rstt] in Z+: robot r charges at st starting t for d slots.\n")
        f.write("- b[rt] in R: battery of robot r after slot t.\n")
        f.write("- C[o] in R: completion slot of order o.\n")
        f.write("- sp[g] in R: excess spread of promise group g.\n\n")
        f.write("## Constraints\n1. Demand: sum x = q for every line.\n")
        f.write("2. Pod inventory: sum x <= inv for every pod-SKU.\n")
        f.write("3. Linking: x <= q*z.\n")
        f.write("4. Split limit: sum z <= maxSplit per order.\n")
        f.write("5. Release: z=0 for t < release (by variable creation).\n")
        f.write("6. Station visit cap: sum z <= V_st per station-slot.\n")
        f.write("7. Units per visit: sum x <= U_st.\n")
        f.write("8. Station active-order windows.\n")
        f.write("9. Pod return buffer: pairwise conflict constraints.\n")
        f.write("10. Robot assignment: sum a = z.\n")
        f.write("11. Robot non-overlap: at most one visit or charge per slot.\n")
        f.write("12. Maintenance and shift: variables excluded.\n")
        f.write("13. Battery: cumulative charge/drain with min/max bounds.\n")
        f.write("14. Charger capacity per station-slot.\n")
        f.write("15. Aisle capacity per aisle-group-slot.\n")
        f.write("16. Completion: C[o] >= t+1 - T*(1-z) for each visit.\n")
        f.write("17. Promise spread: sp[g] >= C[o] - C[o'] - tau_g.\n\n")
        f.write("## Objective (minimize)\n")
        f.write("Weighted sum: tardiness(80), priority_late(220), travel(0.42), charge_time(3.5),\n")
        f.write("energy(0.18), peak_congestion(6.0), split(18), station_imbalance(9), promise_spread(55).\n")


def main():
    cfg = read_config()
    T = cfg["planning_horizon_slots"]
    slots = list(range(T))
    w = cfg["objective_weights"]
    clean_buf = cfg["cleaning_buffer_slots"]
    max_pri_late = cfg["max_order_lateness_slots_for_priority_orders"]
    tol = cfg["solution_tolerance"]

    stations = read_csv(os.path.join(DATA_DIR, "stations.csv"))
    station_windows = read_csv(os.path.join(DATA_DIR, "station_windows.csv"))
    zones = read_csv(os.path.join(DATA_DIR, "zones.csv"))
    robots = read_csv(os.path.join(DATA_DIR, "robots.csv"))
    maint = read_csv(os.path.join(DATA_DIR, "robot_maintenance_windows.csv"))
    skus = read_csv(os.path.join(DATA_DIR, "skus.csv"))
    pods = read_csv(os.path.join(DATA_DIR, "pods.csv"))
    pod_inv = read_csv(os.path.join(DATA_DIR, "pod_inventory.csv"))
    orders = read_csv(os.path.join(DATA_DIR, "orders.csv"))
    order_lines = read_csv(os.path.join(DATA_DIR, "order_lines.csv"))
    promise_groups = read_csv(os.path.join(DATA_DIR, "promise_groups.csv"))
    aisle_capacity = read_csv(os.path.join(DATA_DIR, "aisle_capacity.csv"))

    # Index data
    st_info = {}
    for r in stations:
        st = r["station_id"]
        st_info[st] = {
            "x": int(r["x"]),
            "y": int(r["y"]),
            "open_cap": int(r["open_order_capacity"]),
            "visits_per_slot": int(r["pod_visits_per_slot"]),
            "max_units": int(r["max_units_per_visit"]),
            "chargers": int(r["charger_slots"]),
            "cold": int(r["allows_cold"]),
            "hazmat": int(r["allows_hazmat"]),
        }

    zone_info = {}
    for r in zones:
        z = r["zone_id"]
        zone_info[z] = {
            "x": int(r["x"]),
            "y": int(r["y"]),
            "aisle": r["aisle_group"],
        }

    robot_info = {}
    for r in robots:
        rid = r["robot_id"]
        robot_info[rid] = {
            "zone": r["start_zone"],
            "cap": float(r["battery_capacity"]),
            "init": float(r["initial_battery"]),
            "min": float(r["min_battery"]),
            "epd": float(r["energy_per_distance"]),
            "cps": float(r["charge_per_slot"]),
            "ss": int(r["shift_start"]),
            "se": int(r["shift_end"]),
        }

    maint_windows = defaultdict(list)
    for r in maint:
        rid = r["robot_id"]
        maint_windows[rid].append((int(r["start_slot"]), int(r["end_slot"])))

    sku_info = {}
    for r in skus:
        s = r["sku_id"]
        sku_info[s] = {
            "temp": r["temperature_class"],
            "hazmat": int(r["hazmat"]),
            "fragile": int(r["fragile"]),
            "pick_time": int(r["unit_pick_time"]),
        }

    pod_info = {}
    for r in pods:
        p = r["pod_id"]
        pod_info[p] = {
            "zone": r["zone_id"],
            "temp": r["temperature_capability"],
            "weight": r["weight_class"],
            "buf": int(r["return_buffer_slots"]),
        }

    inv = defaultdict(float)
    for r in pod_inv:
        inv[(r["pod_id"], r["sku_id"])] += float(r["quantity"])

    order_info = {}
    for r in orders:
        o = r["order_id"]
        order_info[o] = {
            "release": int(r["release_slot"]),
            "due": int(r["due_slot"]),
            "priority": r["priority"],
            "temp": r["temperature_class"],
            "hazmat": int(r["hazmat"]),
            "max_split": int(r["max_split_pods"]),
        }

    lines = defaultdict(list)
    for r in order_lines:
        lines[r["order_id"]].append((r["sku_id"], int(r["quantity"])))

    pg_info = defaultdict(list)
    pg_target = {}
    for r in promise_groups:
        g = r["group_id"]
        pg_info[g].append(r["order_id"])
        pg_target[g] = int(r["target_spread_slots"])

    aisle_cap_data = {}
    aisle_peak = {}
    for r in aisle_capacity:
        a = r["aisle_group"]
        t = int(r["slot"])
        aisle_cap_data[(a, t)] = int(r["capacity"])
        aisle_peak[(a, t)] = int(r["peak"])

    def dist(pod, st):
        pz = pod_info[pod]["zone"]
        zx = zone_info[pz]["x"]
        zy = zone_info[pz]["y"]
        sx = st_info[st]["x"]
        sy = st_info[st]["y"]
        return abs(zx - sx) + abs(zy - sy)

    def order_station_ok(o, st):
        oi = order_info[o]
        si = st_info[st]
        if oi["temp"] == "cold" and not si["cold"]:
            return False
        if oi["hazmat"] and not si["hazmat"]:
            return False
        return True

    def pod_order_ok(p, o):
        pi = pod_info[p]
        oi = order_info[o]
        if oi["temp"] == "cold":
            if pi["temp"] not in ("cold", "controlled"):
                return False
        for (s, q) in lines[o]:
            si = sku_info[s]
            if si["fragile"] and pi["weight"] == "heavy":
                return False
        return True

    def pod_has_sku(p, o):
        for (s, q) in lines[o]:
            if inv.get((p, s), 0) > 0:
                return True
        return False

    # Build eligible visit tuples
    eligible_visits = []
    for o in order_info:
        rel = order_info[o]["release"]
        for st in st_info:
            if not order_station_ok(o, st):
                continue
            for p in pod_info:
                if not pod_order_ok(p, o):
                    continue
                if not pod_has_sku(p, o):
                    continue
                for t in range(rel, T):
                    eligible_visits.append((o, p, st, t))

    print(f"Eligible visit tuples: {len(eligible_visits)}")

    # Build MIP
    model = Model("rfc")
    model.setParam("gaprel", 0.0005)

    time_limit = 300.0
    env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env_limit is not None:
        try:
            time_limit = min(time_limit, float(env_limit))
        except ValueError:
            pass
    model.setParam("limits/time", time_limit)

    # Variables
    z = {}
    x = {}
    a = {}
    ch = {}
    d = {}
    b = {}
    C = {}
    tard = {}
    sp = {}
    dev = {}
    phi = {}

    # Create visit variables
    for (o, p, st, t) in eligible_visits:
        z[(o, p, st, t)] = model.addVar(name=f"z_{o}_{p}_{st}_{t}", vtype="B", lb=0, ub=1, obj=0.0)

    # Create pick variables
    for (o, p, st, t) in eligible_visits:
        for li, (s, q) in enumerate(lines[o]):
            if inv.get((p, s), 0) > 0:
                x[(o, li, p, st, t)] = model.addVar(name=f"x_{o}_{li}_{p}_{st}_{t}", vtype="I", lb=0, ub=q, obj=0.0)

    # Create robot assignment variables
    for (o, p, st, t) in eligible_visits:
        for r in robot_info:
            ri = robot_info[r]
            if t < ri["ss"] or t >= ri["se"]:
                continue
            conflict = False
            for (ms, me) in maint_windows.get(r, []):
                if t >= ms and t < me:
                    conflict = True
                    break
            if conflict:
                continue
            a[(o, p, st, t, r)] = model.addVar(name=f"a_{o}_{p}_{st}_{t}_{r}", vtype="B", lb=0, ub=1, obj=0.0)

    # Create charge variables
    for r in robot_info:
        ri = robot_info[r]
        for st in st_info:
            for t in range(ri["ss"], ri["se"]):
                conflict = False
                for (ms, me) in maint_windows.get(r, []):
                    if t >= ms and t < me:
                        conflict = True
                        break
                if conflict:
                    continue
                ch[(r, st, t)] = model.addVar(name=f"ch_{r}_{st}_{t}", vtype="B", lb=0, ub=1, obj=0.0)
                d[(r, st, t)] = model.addVar(name=f"d_{r}_{st}_{t}", vtype="I", lb=0, ub=ri["se"] - t, obj=0.0)

    # Create battery variables
    for r in robot_info:
        for t in slots:
            b[(r, t)] = model.addVar(name=f"b_{r}_{t}", vtype="C", lb=0, ub=robot_info[r]["cap"], obj=0.0)

    # Create completion time variables
    for o in order_info:
        C[o] = model.addVar(name=f"C_{o}", vtype="C", lb=0, ub=T, obj=0.0)

    # Create tardiness variables
    for o in order_info:
        tard[o] = model.addVar(name=f"tard_{o}", vtype="C", lb=0, ub=T, obj=0.0)

    # Create spread variables
    for g in pg_info:
        sp[g] = model.addVar(name=f"spread_{g}", vtype="C", lb=0, ub=T, obj=0.0)

    # Station imbalance deviation variables
    total_visits_ub = len(eligible_visits)
    for st in st_info:
        dev[st] = model.addVar(name=f"dev_{st}", vtype="C", lb=0, ub=total_visits_ub, obj=0.0)

    # Station active-order binary phi
    for o in order_info:
        for st in st_info:
            if not order_station_ok(o, st):
                continue
            phi[(o, st)] = model.addVar(name=f"phi_{o}_{st}", vtype="B", lb=0, ub=1, obj=0.0)

    # Constraints
    # 1. Demand
    for o in order_info:
        for li, (s, q) in enumerate(lines[o]):
            terms = []
            for (o2, p, st, t) in eligible_visits:
                if o2 == o and (o, li, p, st, t) in x:
                    terms.append(x[(o, li, p, st, t)])
            if terms:
                model.addCons(quicksum(terms) == q, name=f"demand_{o}_{li}")

    # 2. Pod inventory
    for p in pod_info:
        for s in sku_info:
            if inv.get((p, s), 0) > 0:
                terms = []
                for (o, li, p2, st, t) in x:
                    if p2 == p and lines[o][li][0] == s:
                        terms.append(x[(o, li, p2, st, t)])
                if terms:
                    model.addCons(quicksum(terms) <= inv[(p, s)], name=f"inv_{p}_{s}")

    # 3. Linking x <= q*z
    for (o, li, p, st, t) in x:
        model.addCons(x[(o, li, p, st, t)] <= lines[o][li][1] * z[(o, p, st, t)],
                      name=f"xz_{o}_{li}_{p}_{st}_{t}")

    # 4. Split limit
    for o in order_info:
        terms = [z[(o, p, st, t)] for (o2, p, st, t) in eligible_visits if o2 == o]
        if terms:
            model.addCons(quicksum(terms) <= order_info[o]["max_split"], name=f"split_{o}")

    # 5. Station per-slot visit cap
    for st in st_info:
        for t in slots:
            terms = [z[(o, p, st2, t2)] for (o, p, st2, t2) in eligible_visits if st2 == st and t2 == t]
            if terms:
                model.addCons(quicksum(terms) <= st_info[st]["visits_per_slot"], name=f"stcap_{st}_{t}")

    # 6. Units per visit
    for (o, p, st, t) in eligible_visits:
        terms = [x[(o, li, p, st, t)] for li in range(len(lines[o])) if (o, li, p, st, t) in x]
        if terms:
            model.addCons(quicksum(terms) <= st_info[st]["max_units"], name=f"units_{o}_{p}_{st}_{t}")

    # 7. Robot assignment
    for (o, p, st, t) in eligible_visits:
        terms = [a[(o, p, st, t, r)] for r in robot_info if (o, p, st, t, r) in a]
        if terms:
            model.addCons(quicksum(terms) == z[(o, p, st, t)], name=f"assign_{o}_{p}_{st}_{t}")

    # 8. Robot non-overlap
    for r in robot_info:
        for t in slots:
            terms = [a[(o, p, st, t, r)] for (o, p, st, t2, r2) in a if r2 == r and t2 == t]
            ch_terms = [ch[(r, st, t)] for st in st_info if (r, st, t) in ch]
            all_terms = terms + ch_terms
            if all_terms:
                model.addCons(quicksum(all_terms) <= 1, name=f"nonoverlap_{r}_{t}")

    # 9. Charge duration linking
    for r in robot_info:
        for st in st_info:
            for t in slots:
                if (r, st, t) in ch:
                    model.addCons(d[(r, st, t)] <= (robot_info[r]["se"] - t) * ch[(r, st, t)],
                                  name=f"chdur_{r}_{st}_{t}")

    # 10. Charger capacity
    for st in st_info:
        for t in slots:
            terms = [ch[(r, st, t)] for r in robot_info if (r, st, t) in ch]
            if terms:
                model.addCons(quicksum(terms) <= st_info[st]["chargers"], name=f"charger_{st}_{t}")

    # 11. Aisle capacity
    aisle_groups = set(z["aisle_group"] for z in zone_info.values())
    for ag in aisle_groups:
        for t in slots:
            cap = aisle_cap_data.get((ag, t), 0)
            if cap > 0:
                terms = []
                for (o, p, st, t2) in eligible_visits:
                    if t2 == t and zone_info[pod_info[p]["zone"]]["aisle_group"] == ag:
                        terms.append(z[(o, p, st, t2)])
                if terms:
                    model.addCons(quicksum(terms) <= cap, name=f"aisle_{ag}_{t}")

    # 12. Completion time linearization
    for o in order_info:
        for (o2, p, st, t) in eligible_visits:
            if o2 == o:
                model.addCons(C[o] >= (t + 1) - T * (1 - z[(o, p, st, t)]),
                              name=f"comp_{o}_{p}_{st}_{t}")

    # 13. Tardiness
    for o in order_info:
        due = order_info[o]["due"]
        model.addCons(tard[o] >= C[o] - due, name=f"tard_def_{o}")

    # 14. Promise spread
    for g in pg_info:
        members = pg_info[g]
        tau = pg_target[g]
        for i, o1 in enumerate(members):
            for o2 in members[i + 1:]:
                model.addCons(sp[g] >= C[o1] - C[o2] - tau, name=f"sp_{g}_{o1}_{o2}")
                model.addCons(sp[g] >= C[o2] - C[o1] - tau, name=f"sp_{g}_{o2}_{o1}")

    # 15. Station active-order windows
    for sw in station_windows:
        st = sw["station_id"]
        s_start = int(sw["start_slot"])
        s_end = int(sw["end_slot"])
        max_active = int(sw["max_active_orders"])
        terms = [phi[(o, st)] for o in order_info if (o, st) in phi]
        if terms:
            model.addCons(quicksum(terms) <= max_active, name=f"win_{st}_{s_start}_{s_end}")

    # phi linking
    for (o, st) in phi:
        terms = [z[(o, p, st, t)] for (o2, p, st2, t) in eligible_visits if o2 == o and st2 == st]
        if terms:
            model.addCons(phi[(o, st)] >= z[(o, p, st, t)] for (o2, p, st2, t) in eligible_visits if o2 == o and st2 == st)

    # 16. Pod return buffer
    for p in pod_info:
        buf = pod_info[p]["buf"]
        p_visits = [(o, p, st, t) for (o, p2, st, t) in eligible_visits if p2 == p]
        for i, (o1, p1, st1, t1) in enumerate(p_visits):
            for (o2, p2, st2, t2) in p_visits[i + 1:]:
                if abs(t1 - t2) < buf:
                    model.addCons(z[(o1, p1, st1, t1)] + z[(o2, p2, st2, t2)] <= 1,
                                  name=f"buf_{p}_{t1}_{t2}")

    # 17. Battery constraints
    for r in robot_info:
        ri = robot_info[r]
        for t in slots:
            # Battery after slot t >= initial + cumulative charge - cumulative drain
            charge_terms = []
            for st in st_info:
                for t0 in range(ri["ss"], t + 1):
                    if (r, st, t0) in ch:
                        charge_terms.append(ri["cps"] * ch[(r, st, t0)])
            drain_terms = []
            for (o, p, st, t2, r2) in a:
                if r2 == r and t2 <= t:
                    drain_terms.append(ri["epd"] * dist(p, st) * a[(o, p, st, t2, r2)])
            model.addCons(
                b[(r, t)] >= ri["init"] + quicksum(charge_terms) - quicksum(drain_terms),
                name=f"bat_lo_{r}_{t}")
            model.addCons(b[(r, t)] <= ri["cap"], name=f"bat_hi_{r}_{t}")
            model.addCons(b[(r, t)] >= ri["min"], name=f"bat_min_{r}_{t}")

    # 18. Station imbalance
    st_visit_count = {}
    for st in st_info:
        terms = [z[(o, p, st, t)] for (o, p, st2, t) in eligible_visits if st2 == st]
        st_visit_count[st] = terms
        n_st = len(st_info)
        # dev[st] >= count - avg, dev[st] >= avg - count
        # avg = total/n_st; use linear form: dev >= count - total/n_st
        total_terms = []
        for st2 in st_info:
            total_terms.extend(st_visit_count[st2])
        if terms:
            model.addCons(dev[st] >= quicksum(terms) - quicksum(total_terms) / n_st,
                          name=f"imb_lo_{st}")
            model.addCons(dev[st] >= quicksum(total_terms) / n_st - quicksum(terms),
                          name=f"imb_hi_{st}")

    # Objective
    obj_terms = []

    # Weighted tardiness
    for o in order_info:
        pi = 2 if order_info[o]["priority"] == "priority" else 1
        obj_terms.append(w["weighted_tardiness"] * pi * tard[o])

    # Priority late (capped)
    for o in order_info:
        if order_info[o]["priority"] == "priority":
            obj_terms.append(w["priority_late"] * tard[o])

    # Visit travel
    for (o, p, st, t) in eligible_visits:
        obj_terms.append(w["visit_travel"] * dist(p, st) * z[(o, p, st, t)])

    # Charge time
    for (r, st, t) in d:
        obj_terms.append(w["charge_time"] * d[(r, st, t)])

    # Energy used
    for r in robot_info:
        ri = robot_info[r]
        obj_terms.append(w["energy_used"] * (ri["init"] - b[(r, ri["se"] - 1)]))

    # Peak congestion
    for ag in aisle_groups:
        for t in slots:
            if aisle_peak.get((ag, t), 0) == 1:
                for (o, p, st, t2) in eligible_visits:
                    if t2 == t and zone_info[pod_info[p]["zone"]]["aisle_group"] == ag:
                        obj_terms.append(w["peak_congestion"] * z[(o, p, st, t2)])

    # Split order
    for o in order_info:
        terms = [z[(o, p, st, t)] for (o2, p, st, t) in eligible_visits if o2 == o]
        if terms:
            obj_terms.append(w["split_order"] * (quicksum(terms) - 1))

    # Station imbalance
    for st in st_info:
        obj_terms.append(w["station_imbalance"] * dev[st])

    # Promise spread
    for g in pg_info:
        obj_terms.append(w["promise_group_spread"] * sp[g])

    obj_expr = quicksum(obj_terms)
    model.setObjective(obj_expr, sense="minimize")

    print("Model built, optimizing...")
    print(f"Vars: {model.getNVars()}, Cons: {model.getNCons()}")

    try:
        model.optimize()
    except Exception as e:
        print(f"Solver error: {e}")
        # Write empty solution
        os.makedirs(SUB_DIR, exist_ok=True)
        with open(SOLUTION_PATH, "w", newline="") as f:
            wtr = csv.writer(f)
            wtr.writerow(["row_type", "visit_id", "order_id", "pod_id", "sku_id", "robot_id", "station_id", "start_slot", "quantity"])
        return

    status = model.getStatus()
    print(f"Status: {status}")
    try:
        obj_val = model.getObjVal()
        print(f"Objective: {obj_val:.8f}")
    except Exception:
        obj_val = None
        print("Objective: N/A")
    print(f"NSols: {model.getNSols()}")

    sol = model.getBestSol()
    if sol is None:
        print("No solution found!")
        os.makedirs(SUB_DIR, exist_ok=True)
        with open(SOLUTION_PATH, "w", newline="") as f:
            wtr = csv.writer(f)
            wtr.writerow(["row_type", "visit_id", "order_id", "pod_id", "sku_id", "robot_id", "station_id", "start_slot", "quantity"])
        return

    # Build output
    rows = []
    visit_id_counter = 0
    visit_map = {}

    for (o, p, st, t), var in z.items():
        val = model.getVal(var)
        if val > 0.5:
            r_assigned = None
            for r in robot_info:
                if (o, p, st, t, r) in a:
                    rval = model.getVal(a[(o, p, st, t, r)])
                    if rval > 0.5:
                        r_assigned = r
                        break
            if r_assigned is None:
                r_assigned = "RB01"
            visit_id_counter += 1
            vid = f"V{visit_id_counter:04d}"
            visit_map[(o, p, st, t)] = (vid, r_assigned)
            rows.append(["visit", vid, "", p, "", r_assigned, st, str(t), ""])

    for (o, li, p, st, t), var in x.items():
        val = model.getVal(var)
        if val > 0.5:
            if (o, p, st, t) in visit_map:
                vid, r = visit_map[(o, p, st, t)]
                s = lines[o][li][0]
                rows.append(["pick", vid, o, "", s, "", "", "", str(int(round(val)))])

    for (r, st, t), var in ch.items():
        val = model.getVal(var)
        if val > 0.5:
            dur = model.getVal(d[(r, st, t)])
            if dur > 0.5:
                rows.append(["charge", "", "", "", "", r, st, str(t), str(int(round(dur)))])

    os.makedirs(SUB_DIR, exist_ok=True)
    with open(SOLUTION_PATH, "w", newline="") as f:
        wtr = csv.writer(f)
        wtr.writerow(["row_type", "visit_id", "order_id", "pod_id", "sku_id", "robot_id", "station_id", "start_slot", "quantity"])
        for row in rows:
            wtr.writerow(row)

    print(f"Wrote {len(rows)} rows to {SOLUTION_PATH}")

    # Validation
    print("\n--- Validation ---")
    # Check demand
    demand_ok = True
    for o in order_info:
        for li, (s, q) in enumerate(lines[o]):
            total = 0
            for (o2, li2, p, st, t), var in x.items():
                if o2 == o and li2 == li:
                    total += model.getVal(var)
            if abs(total - q) > tol:
                demand_ok = False
                print(f"  Demand fail: {o} line {li} ({s}): got {total}, need {q}")
    print(f"  Demand satisfied: {demand_ok}")

    # Check split limits
    split_ok = True
    for o in order_info:
        cnt = 0
        for (o2, p, st, t), var in z.items():
            if o2 == o and model.getVal(var) > 0.5:
                cnt += 1
        if cnt > order_info[o]["max_split"]:
            split_ok = False
            print(f"  Split fail: {o}: {cnt} > {order_info[o]['max_split']}")
    print(f"  Split limits: {split_ok}")

    print(f"  Total visits: {visit_id_counter}")


if __name__ == "__main__":
    write_model_md()
    main()
